const isRecord = (value: unknown): value is RuntimeRecord =>
  value !== null && typeof value === "object" && !Array.isArray(value);

const validationFailure = (field: string, message: string): never => {
  throw new SdkValidationError(field, "required", message);
};

const requiredValue = (field: string): never =>
  validationFailure(field, `Validation failed for '${field}': value is required`);

const childField = (field: string, property: string): string =>
  field ? `${field}.${property}` : property;

const hasType = (schema: RuntimeSchema, type: string): boolean =>
  schema.type === type || (Array.isArray(schema.type) && schema.type.includes(type));

const validateNode = (value: unknown, schema: RuntimeSchema, field: string): unknown => {
  if (value === null) {
    if (schema.nullable === true || hasType(schema, "null")) return value;
    return validationFailure(field, `Validation failed for '${field}': value is not nullable`);
  }

  if (schema.ref) {
    const referenced = modelSchemas[schema.ref];
    return referenced ? validateNode(value, referenced, field) : value;
  }

  if (schema.allOf) {
    for (const member of schema.allOf) validateNode(value, member, field);
  }

  if (schema.oneOf || schema.anyOf) {
    const members = schema.oneOf ?? schema.anyOf ?? [];
    let firstError: unknown;
    for (const member of members) {
      try {
        return validateNode(value, member, field);
      } catch (error) {
        firstError ??= error;
      }
    }
    if (firstError instanceof Error) throw firstError;
  }

  if (hasType(schema, "object") || schema.properties) {
    if (!isRecord(value)) return value;
    for (const property of schema.required ?? []) {
      const propertyValue = value[property];
      if (!Object.prototype.hasOwnProperty.call(value, property) || propertyValue === undefined) {
        requiredValue(childField(field, property));
      }
    }
    for (const [property, propertySchema] of Object.entries(schema.properties ?? {})) {
      if (Object.prototype.hasOwnProperty.call(value, property)) {
        validateNode(value[property], propertySchema, childField(field, property));
      }
    }
    if (schema.additionalProperties) {
      for (const [property, propertyValue] of Object.entries(value)) {
        if (!(property in (schema.properties ?? {}))) {
          validateNode(propertyValue, schema.additionalProperties, childField(field, property));
        }
      }
    }
  }

  if (hasType(schema, "array")) {
    if (!Array.isArray(value)) return value;
    if (schema.items) {
      value.forEach((item, index) =>
        validateNode(item, schema.items as RuntimeSchema, childField(field, String(index))),
      );
    }
  }

  if (schema.enum) validateEnum(field, value, schema.enum);

  if (
    schema.minimum !== undefined ||
    schema.maximum !== undefined ||
    schema.exclusiveMinimum !== undefined ||
    schema.exclusiveMaximum !== undefined ||
    schema.multipleOf !== undefined
  ) {
    validateRange(field, value as number, {
      ...(typeof schema.minimum === "number" ? { min: schema.minimum } : {}),
      ...(typeof schema.maximum === "number" ? { max: schema.maximum } : {}),
      ...(typeof schema.exclusiveMinimum === "number"
        ? { exclusiveMin: schema.exclusiveMinimum }
        : {}),
      ...(typeof schema.exclusiveMaximum === "number"
        ? { exclusiveMax: schema.exclusiveMaximum }
        : {}),
      ...(typeof schema.multipleOf === "number" ? { multipleOf: schema.multipleOf } : {}),
    });
  }

  if (schema.minLength !== undefined || schema.maxLength !== undefined) {
    validateLength(field, value as string, {
      ...(schema.minLength !== undefined ? { min: schema.minLength } : {}),
      ...(schema.maxLength !== undefined ? { max: schema.maxLength } : {}),
    });
  }

  if (schema.minItems !== undefined || schema.maxItems !== undefined) {
    validateItems(field, value as readonly unknown[], {
      ...(schema.minItems !== undefined ? { min: schema.minItems } : {}),
      ...(schema.maxItems !== undefined ? { max: schema.maxItems } : {}),
    });
  }

  if (schema.pattern) validatePattern(field, value as string, schema.pattern);

  if (schema.format === "email") validateEmail(field, value as string);

  if (schema.format === "uuid") validateUuid(field, value as string);

  if (schema.format === "date") validateDate(field, value as string);

  if (schema.format === "date-time") validateDateTime(field, value as string);

  return value;
};

/** Validates a decoded component model and returns the original value. */
export function decodeModel<T>(value: unknown, typeName: string): T {
  const schema = modelSchemas[typeName];
  if (!schema) return value as T;
  return validateNode(value, schema, "") as T;
}
